import gradio as gr

# JavaScript functions to show/hide the modal
def show_modal(type, msg):
    return f'''
    <style>
        .modal {{
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background-color: rgba(0, 0, 0, 0.5);
            z-index: 9999;
            display: flex;
            justify-content: center;
            align-items: center;
        }}
        .modal-content {{
            background-color: #333;
            padding: 20px;
            border-radius: 8px;
            text-align: center;
            max-width: 300px;
            box-shadow: 0 4px 8px rgba(0, 0, 0, 0.5);
            border: 2px solid #FFA500;
            color: white;
            position: relative;
        }}
        .confirm-buttons {{
            display: flex;
            justify-content: space-evenly;
            margin-top: 20px;
        }}
        .confirm-buttons button {{
            padding: 10px 20px;
            border: none;
            border-radius: 5px;
            font-size: 16px;
            cursor: pointer;
        }}
        .confirm_yes_btn {{ background-color: #28a745; color: white; }}
        .confirm_no_btn {{ background-color: #dc3545; color: white; }}
    </style>
    <div id="custom-modal" class="modal">
        <div class="modal-content">
            <p>{msg}</p>
            {show_confirm() if type == 'confirm' else '<div class="spinner"></div>'}
        </div>
    </div>
    '''

def show_confirm():
    return '''
    <div class="confirm-buttons">
        <button class="confirm_yes_btn" onclick="document.getElementById('confirm_yes_btn').click()">✔</button>
        <button class="confirm_no_btn" onclick="document.getElementById('confirm_no_btn').click()">⨉</button>
    </div>
    '''

# Gradio Interface
with gr.Blocks() as demo:
    modal_html = gr.HTML()
    result_text = gr.Textbox(label="Result")

    confirm_yes_btn = gr.Button("", elem_id="confirm_yes_btn", visible=False)
    confirm_no_btn = gr.Button("", elem_id="confirm_no_btn", visible=False)

    def on_yes():
        return "ok", ""

    def on_no():
        return gr.update(), ""

    def open_modal():
        return show_modal('confirm', 'Are you sure you want to continue?')

    trigger_modal_btn = gr.Button("Show Modal")

    trigger_modal_btn.click(open_modal, outputs=modal_html)
    confirm_yes_btn.click(on_yes, outputs=[result_text, modal_html])
    confirm_no_btn.click(on_no, outputs=[result_text, modal_html])

demo.launch()
```
